import type { ImageSourcePropType } from 'react-native';
import type { VideoSource } from 'expo-video';

export interface Clip {
  id: string;
  /** A bundled asset (`require`) or a remote `{ uri }`. */
  video: VideoSource;
  poster: ImageSourcePropType;
  author: string;
  verified: boolean;
  caption: string;
  audio: string;
  likes: number;
  comments: number;
  shares: number;
}

// Original placeholder media generated by scripts/generate-media.sh.
const MEDIA = [
  { video: require('../../assets/media/aurora.mp4'), poster: require('../../assets/media/aurora.jpg') },
  { video: require('../../assets/media/fractal.mp4'), poster: require('../../assets/media/fractal.jpg') },
  { video: require('../../assets/media/petri.mp4'), poster: require('../../assets/media/petri.jpg') },
  { video: require('../../assets/media/sunset.mp4'), poster: require('../../assets/media/sunset.jpg') },
  { video: require('../../assets/media/rule110.mp4'), poster: require('../../assets/media/rule110.jpg') },
  { video: require('../../assets/media/nebula.mp4'), poster: require('../../assets/media/nebula.jpg') },
  { video: require('../../assets/media/drift.mp4'), poster: require('../../assets/media/drift.jpg') },
  { video: require('../../assets/media/tide.mp4'), poster: require('../../assets/media/tide.jpg') },
];

const AUTHORS = [
  ['lumen.lab', true],
  ['fieldnotes', false],
  ['pixel_garden', true],
  ['quiet.static', false],
  ['north_studio', true],
  ['half.tone', false],
  ['moth_and_lamp', false],
  ['signal.daily', true],
] as const;

const CAPTIONS = [
  'Took me three tries to get this shot. Worth it? #loop',
  'Would you have guessed this one? Be honest 👀 #doubletake',
  'Rendering this took longer than I want to admit…',
  'Save this for when you need five calm seconds.',
  'Real footage or generated? Comment your guess before you check.',
  'The colors on this are unreal. Literally — check the description.',
  'Part 2 because you asked. Part 3 if this hits 10k ✨',
  'No filters. Okay, one filter. Okay, several.',
];

const AUDIO = ['Original audio', 'Low Tide · Ambient Loops', 'Studio Hum · Field Recordings', 'Slow Bloom · Night Drive'];

// Deterministic pseudo-random so counts are stable between reloads.
function rand(seed: number) {
  const x = Math.sin(seed * 9301 + 49297) * 233280;
  return x - Math.floor(x);
}

export function makeClips(start: number, n: number): Clip[] {
  return Array.from({ length: n }, (_, k) => {
    const i = start + k;
    const media = MEDIA[i % MEDIA.length];
    const [author, verified] = AUTHORS[(i * 3) % AUTHORS.length];
    const likes = Math.floor(rand(i) * rand(i + 1) * 900_000) + 120;
    return {
      id: `clip-${i}`,
      video: media.video,
      poster: media.poster,
      author,
      verified,
      caption: CAPTIONS[(i * 5) % CAPTIONS.length],
      audio: AUDIO[i % AUDIO.length],
      likes,
      comments: Math.floor(likes * (0.004 + rand(i + 2) * 0.02)),
      shares: Math.floor(likes * (0.01 + rand(i + 4) * 0.05)),
    };
  });
}

export function formatCount(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1).replace(/\.0$/, '')}M`;
  if (n >= 10_000) return `${(n / 1000).toFixed(n >= 100_000 ? 0 : 1).replace(/\.0$/, '')}K`;
  return n.toLocaleString('en-US');
}

export function avatarHue(name: string): number {
  let x = 0;
  for (const c of name) x = (x * 31 + c.charCodeAt(0)) % 360;
  return x;
}
